.yagr {
  --yagr-font-family:
    "Roboto",
    "Helvetica Neue",
    "Helvetica",
    arial,
    sans-serif;
}
.yagr_theme_light,
.yagr_theme_light-hc {
  --yagr-title-color: #333333;
  --yagr-legend-item: rgba(0, 0, 0, 0.5);
  --yagr-legend-item-hover: #000000;
  --yagr-legend-item-hidden: rgba(0, 0, 0, 0.3);
  --yagr-background: #ffffff;
  --yagr-grid: rgba(0, 0, 0, 0.105);
  --yagr-axis-stroke: rgba(0, 0, 0, 0.5);
}
.yagr_theme_dark,
.yagr_theme_dark-hc {
  --yagr-title-color: rgba(255, 255, 255, 0.35);
  --yagr-legend-item: rgba(255, 255, 255, 0.5);
  --yagr-legend-item-hover: #a09fa3;
  --yagr-legend-item-hidden: hsla(0, 0%, 100%, 0.17);
  --yagr-background: #2d2c33;
  --yagr-grid: rgba(255, 255, 255, 0.23);
  --yagr-axis-stroke: rgba(255, 255, 255, 0.5);
}
.yagr_theme_dark-hc {
  --yagr-background: rgba(34, 35, 38, 1);
}
.yagr {
  width: 100%;
  height: 100%;
  font-family: var(--yagr-font-family);
  background-color: var(--yagr-background);
  overflow: hidden;
}
.yagr .uplot {
  width: 100%;
  font-family: var(--yagr-font-family);
}
.yagr .u-title {
  color: var(--yagr-title-color);
  font-size: 14px;
  font-weight: bold;
  line-height: 14px;
  margin-top: 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.yagr .u-select {
  background: rgba(51, 92, 173, 0.25);
}
.uplot,
.uplot *,
.uplot *::before,
.uplot *::after {
  box-sizing: border-box;
}
.uplot {
  font-family:
    system-ui,
    -apple-system,
    "Segoe UI",
    Roboto,
    "Helvetica Neue",
    Arial,
    "Noto Sans",
    sans-serif,
    "Apple Color Emoji",
    "Segoe UI Emoji",
    "Segoe UI Symbol",
    "Noto Color Emoji";
  line-height: 1.5;
  width: min-content;
}
.u-title {
  text-align: center;
  font-size: 18px;
  font-weight: bold;
}
.u-wrap {
  position: relative;
  user-select: none;
}
.u-over,
.u-under {
  position: absolute;
}
.u-under {
  overflow: hidden;
}
.uplot canvas {
  display: block;
  position: relative;
  width: 100%;
  height: 100%;
}
.u-axis {
  position: absolute;
}
.u-legend {
  font-size: 14px;
  margin: auto;
  text-align: center;
}
.u-inline {
  display: block;
}
.u-inline * {
  display: inline-block;
}
.u-inline tr {
  margin-right: 16px;
}
.u-legend th {
  font-weight: 600;
}
.u-legend th > * {
  vertical-align: middle;
  display: inline-block;
}
.u-legend .u-marker {
  width: 1em;
  height: 1em;
  margin-right: 4px;
  background-clip: padding-box !important;
}
.u-inline.u-live th::after {
  content: ":";
  vertical-align: middle;
}
.u-inline:not(.u-live) .u-value {
  display: none;
}
.u-series > * {
  padding: 4px;
}
.u-series th {
  cursor: pointer;
}
.u-legend .u-off > * {
  opacity: 0.3;
}
.u-select {
  background: rgba(0, 0, 0, 0.07);
  position: absolute;
  pointer-events: none;
}
.u-cursor-x,
.u-cursor-y {
  position: absolute;
  left: 0;
  top: 0;
  pointer-events: none;
  will-change: transform;
}
.u-hz .u-cursor-x,
.u-vt .u-cursor-y {
  height: 100%;
  border-right: 1px dashed #607D8B;
}
