  const browser = await chromium.launch({args: ['--no-sandbox']});
  const page = await browser.newPage({viewport: {width: 1100, height: 520}, deviceScaleFactor: 2});
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.type() + ': ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:5199/.harness-tmp/index.html');
  await page.waitForSelector('.cpu-load-chart__canvas canvas', {timeout: 15000});
  await page.waitForTimeout(800);
  const info = await page.evaluate(() => {
