      libXi.so*) pkg=libxi6;;
      libXrender*) pkg=libxrender1;;
      libxshmfence*) pkg=libxshmfence1;;
    esac
    echo " -> $pkg"; apt-get download $pkg >/dev/null 2>&1 || echo "  fail $pkg"
  done
done

