    const c = document.querySelector('.cpu-load-chart__canvas canvas');
    return {canvases: document.querySelectorAll('.cpu-load-chart__canvas canvas').length, w: c.clientWidth, h: c.clientHeight,
      stats: [...document.querySelectorAll('.cpu-load-chart__stat-value')].map(e => e.textContent), timers: window.__timers.size, ro: window.__ro,
      tooltips: document.querySelectorAll('.yagr-tooltip').length};
  });
  console.log('initial', JSON.stringify(info));
  await page.screenshot({path: '/tmp/pwcheck/light.png'});

  // hover tooltip
  const box = await page.locator('.cpu-load-chart__canvas').boundingBox();
  await page.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.5);
  await page.waitForTimeout(200);
  console.log('tooltip', await page.evaluate(() => { const t = document.querySelector('.cpu-load-tooltip'); return t && getComputedStyle(t).display + ' | ' + t.textContent; }));
  await page.screenshot({path: '/tmp/pwcheck/hover.png'});

  // hover perf: many mouse moves
  const t0 = Date.now();
  for (let i = 0; i < 120; i++) await page.mouse.move(box.x + 60 + i * 7, box.y + box.height * 0.5);
  console.log('120 mousemoves ms', Date.now() - t0);

  // realtime update: wait for stats change & ensure count stable
  const lenBefore = await page.evaluate(() => document.querySelector('.cpu-load-chart__canvas').id);
  await page.mouse.move(5, 5);
  const before = await page.evaluate(() => document.querySelector('.cpu-load-chart__stat-value').textContent);
  await page.waitForTimeout(4500);
  const after = await page.evaluate(() => document.querySelector('.cpu-load-chart__stat-value').textContent);
  console.log('live current', before, '->', after);

  // zoom by drag
  await page.mouse.move(box.x + box.width * 0.4, box.y + box.height * 0.5);
  await page.mouse.down();
  await page.mouse.move(box.x + box.width * 0.5, box.y + box.height * 0.5, {steps: 5});
  await page.mouse.up();
  await page.waitForTimeout(300);
  console.log('zoom button visible', await page.locator('text=Сбросить масштаб').isVisible());
  await page.screenshot({path: '/tmp/pwcheck/zoomed.png'});
  await page.mouse.move(5, 5);
  await page.waitForTimeout(4500); // live update while zoomed must keep zoom
  console.log('still zoomed after live update', await page.locator('text=Сбросить масштаб').isVisible());
  await page.locator('text=Сбросить масштаб').click();
  await page.waitForTimeout(300);
  console.log('zoom reset -> button visible', await page.locator('text=Сбросить масштаб').isVisible());

  // resize
  await page.evaluate(() => window.__setWidth('600px'));
  await page.waitForTimeout(300);
  console.log('after shrink canvas w', await page.evaluate(() => document.querySelector('.cpu-load-chart__canvas canvas').clientWidth));
  await page.evaluate(() => window.__setWidth('100%'));
  await page.waitForTimeout(300);
  console.log('after grow canvas w', await page.evaluate(() => document.querySelector('.cpu-load-chart__canvas canvas').clientWidth));

  // theme
  const pixel = () => page.evaluate(() => { const c = document.querySelector('.cpu-load-chart__canvas canvas'); const d = c.getContext('2d').getImageData(c.width - 30, 30, 1, 1).data; return [...d].join(','); });
  console.log('bg pixel light', await pixel());
  await page.evaluate(() => window.__setTheme('dark'));
  await page.waitForTimeout(300);
  console.log('bg pixel dark', await pixel(), 'series color', await page.evaluate(() => document.querySelector('.cpu-load-chart').className));
  await page.screenshot({path: '/tmp/pwcheck/dark.png'});
  await page.mouse.move(box.x + box.width * 0.3, box.y + box.height * 0.5);
  await page.waitForTimeout(200);
  console.log('dark tooltip bg', await page.evaluate(() => getComputedStyle(document.querySelector('.cpu-load-tooltip')).backgroundColor));
  await page.screenshot({path: '/tmp/pwcheck/dark-hover.png'});

  // unmount
  await page.evaluate(() => window.__setMounted(false));
  await page.waitForTimeout(300);
  console.log('after unmount', JSON.stringify(await page.evaluate(() => ({timers: window.__timers.size, ro: window.__ro, tooltips: document.querySelectorAll('.yagr-tooltip').length, canvases: document.querySelectorAll('canvas').length}))));
  await page.waitForTimeout(2500);
  console.log('errors', JSON.stringify(errors, null, 1));
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
EOF
